import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from core.ids import is_valid_household_id  # noqa: E402
from registry.dedup import find_duplicates  # noqa: E402
from registry.register import load_households  # noqa: E402


def main() -> None:
    households = load_households()
    ids = {h.id for h in households}
    problems = []
    if find_duplicates(households):
        problems.append(f"still duplicate groups: {find_duplicates(households)}")
    for h in households:
        if h.status == "active" and not is_valid_household_id(h.id):
            problems.append(f"active record with invalid ID: {h.id}")
        if h.status == "merged" and (h.merged_into not in ids or h.merged_into == h.id):
            problems.append(f"merged record {h.id} has bad merged_into={h.merged_into!r}")
    merged = [h for h in households if h.status == "merged"]
    print(f"{len(households)} records, {len(merged)} merged, {len(households) - len(merged)} active")
    print("OK" if not problems else "PROBLEMS:\n" + "\n".join(problems))


if __name__ == "__main__":
    main()
